#!/bin/bash
# make_boards.sh <final tag> : hair pass P report boards (S = h51a start, F = final; both on the locked m2 + M_SlightArch package, same session / lights)
set -u; cd "/c/Users/berat/OneDrive/Documents/Unreal Projects/ActionAdventureMovementS"; t=${1:?tag}; PY="/c/Program Files/Epic Games/UE_5.8/Engine/Binaries/ThirdParty/Python3/Win64/python.exe"; LB=Tools/CharacterLookdev_20260930/lk_board.py
